            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "عندما تغضب المرأة تفقد ربع جمالها ونصف أنوثتها وكل حبها.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "أن أكبر هزيمة في حياتي هي حرماني من متعة القراءة بعد ضعف نظري.", Author = "نجيب محفوظ" },
