            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "هذه هي الحياة أنك تتنازل عن متعك الواحدة بعد الأخرى حتى لا يبقي منها شيء وعندئذ تعلم أنه قد حان وقت الرحيل.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "الملوك كالشجرة الباسقة أوفى من الحشائش نصيبا من شعاع الشمس ونسائم الهواء وأكثرها تعرضًا لقوًة الريح واقتلاع الزوابع.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "على القاتل أن يحمل ضحيته.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "لا سعادة بلا كرامه لكننا لا نسعد بالكرامة وحدها.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "من الخطأ أن يفكر الإنسان في شئون الناس ما دام هذا لا يورث إلا الضيق.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "قارئ الحرف هو المتعلم وقارئ الكتاب هو المثقف.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "تلوث نفسي أفقدني صراحة الأبرياء.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "سحر النساء يتجلى فيما ينفثن في الحديث التافه من لذة.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "للأعين لغة معجمها الغرائز والأحاسيس.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "عجباً! ما أقدركن أيها النساء على إخفاء مشاعركن وتكلف ما ليس بكن.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "سنظل نختلف في الجمال كما اختلف الذين من قبلنا ولكن حسبي ما تقول النظرية الذاتية، فجمال المرأة هو ما يطيب لي منها.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "إن سعادتنا بأحبائنا اليوم مرتهنة بالدموع التي نسكبها على فراقهم غداً.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "بـحـبـك أكـتـر مـن إمـبـارح وأقـل مـن بُـكـره.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "الـحـاضـر مـا نُـعـانـيـه، والـمـسـتـقـبـل مـا نـأمـل فـيـه، والماضي مـا نُـحـبـه عـدلاً أو ظـلـمـاً.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "القوة الحقيقية هي ليست القوة الجسدية وانا هي القوة العقلية.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "وأن لم تستحي من آلات فإفعل كماشئت", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "القلب يعرف أكثر مما يتصور العقل.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "الخوف لا يمنع من الموت ولكنه يمنع من الحياة.", Author = "نجيب محفوظ" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/نجيب_محفوظ", Text = "إن سعادتنا بأحبائنا اليوم مرتهنة بالدموع التي نسكبها على فراقهم غداً.", Author = "نجيب محفوظ" },
